6	
7	use tauri::Manager;
8	
9	use handlers::{
10	    add_app_dictionary_word, add_dictionary_word, add_site_dictionary_word,
11	    check_accessibility_probe, check_model_downloaded, check_model_status, delete_app_dictionary,
12	    delete_app_dictionary_word, delete_app_instruction, delete_dictionary_word,
13	    delete_site_dictionary, delete_site_dictionary_word, delete_site_style, download_model,
14	    download_whisper_model, get_active_model, get_dictionary_prompt, get_frontmost_app,
15	    list_app_dictionaries, list_app_instructions, list_audio_devices, list_dictionary_words,
16	    list_installed_apps, list_models, list_site_dictionaries, list_site_styles, list_transcriptions,
17	    mute_media_for_recording, process_audio_file, read_audio_file, restore_media_after_recording,
18	    save_transcription, set_active_model, set_app_instruction, set_site_style,
19	    start_recording_with_device, start_system_key_watcher, stop_recording_with_device,
20	    transcribe_audio, type_text, update_app_dictionary_word, update_dictionary_word,
21	    update_site_dictionary_word,
22	};
23	
24	fn install_panic_hook() {
25	    let default_hook = std::panic::take_hook();
26	    std::panic::set_hook(Box::new(move |panic_info| {
27	        let payload = panic_info
28	            .payload()
29	            .downcast_ref::<&str>()
30	            .map(|value| (*value).to_string())
31	            .or_else(|| panic_info.payload().downcast_ref::<String>().cloned())
32	            .unwrap_or_else(|| "unknown panic payload".to_string());
33	
34	        let location = panic_info
35	            .location()
36	            .map(|location| {
37	                format!(
38	                    "{}:{}:{}",
39	                    location.file(),
40	                    location.line(),
41	                    location.column()
42	                )
43	            })
44	            .unwrap_or_else(|| "unknown".to_string());
45	
46	        log::error!(target: "runtime", "rust_panic payload={payload:?} location={location}");
47	
48	        default_hook(panic_info);
49	    }));
50	}
51	
52	#[cfg_attr(mobile, tauri::mobile_entry_point)]
53	pub fn run() {
54	    install_panic_hook();
55	
56	    tauri::Builder::default()
57	        .invoke_handler(tauri::generate_handler![
58	            type_text,
59	            read_audio_file,
60	            process_audio_file,
61	            check_accessibility_probe,
62	            start_system_key_watcher,
63	            list_audio_devices,
64	            mute_media_for_recording,
65	            restore_media_after_recording,
66	            start_recording_with_device,
67	            stop_recording_with_device,
68	            save_transcription,
69	            list_transcriptions,
70	            add_dictionary_word,
71	            list_dictionary_words,
72	            update_dictionary_word,
73	            delete_dictionary_word,
74	            get_dictionary_prompt,
75	            check_model_status,
