1	import { emit, listen } from "@tauri-apps/api/event";
2	import {
3		LogicalPosition,
4		LogicalSize,
5		cursorPosition,
6		getCurrentWindow,
7		monitorFromPoint,
8	} from "@tauri-apps/api/window";
9	import { register, unregister } from "@tauri-apps/plugin-global-shortcut";
10	import { Result } from "better-result";
11	import { Check, X } from "lucide-solid";
12	import { For, Show, createEffect, createSignal, onCleanup, onMount } from "solid-js";
13	import DotMatrixSpinner from "../components/DotMatrixSpinner";
14	import { getFrontmostApp } from "../lib/commands/apps";
15	import { startRecordingWithDevice, stopRecordingWithDevice } from "../lib/commands/audio";
16	import {
17		muteMediaForRecording as muteMediaForRecordingCommand,
18		restoreMediaAfterRecording as restoreMediaAfterRecordingCommand,
19	} from "../lib/commands/media";
20	import { typeText } from "../lib/commands/text";
21	import { saveTranscription, transcribeAudio } from "../lib/commands/transcriptions";
22	import { errorFields, logDiagnostic } from "../lib/diagnostics";
23	import {
24		DEFAULT_HOLD_TO_SPEAK_HOTKEY,
25		DEFAULT_HOTKEY,
26		isValidHotkey,
27		registerDictationHotkeys,
28		unregisterDictationHotkey,
29	} from "../lib/hotkeyUtils";
30	import {
31		loadSettings,
32		updateHoldToSpeakHotkey,
33		updateHotkey,
34		useSettings,
35	} from "../lib/settingsStore";
36	
37	const NUM_BARS = 10;
38	const BAR_INDICES = Array.from({ length: NUM_BARS }, (_, i) => i);
39	const BAR_BASE_HEIGHT = 4;
40	const BAR_MAX_HEIGHT = 18;
41	const BAR_IDLE_AMPLITUDE = 2;
42	const BAR_VOICE_SCALE = 2.5;
43	const WAVE_STEP_MS = 110;
44	const WAVE_PATTERN = [
45		0.25, 0.45, 0.7, 0.9, 1.0, 0.95, 0.75, 0.5, 0.3, 0.4, 0.65, 0.85, 1.0, 0.9, 0.65, 0.35,
46	];
47	
48	const WINDOW_WIDTH_COMPACT = 100;
49	const WINDOW_WIDTH_HANDS_FREE = 140;
50	const WINDOW_HEIGHT = 28;
51	const BOTTOM_PADDING = 20;
52	const VOXFUSION_BUNDLE_ID = "io.voxfusion.app";
53	
54	let lastMonitorX: number | null = null;
55	let lastMonitorY: number | null = null;
56	let currentWindowWidth = WINDOW_WIDTH_COMPACT;
57	
58	async function setWindowWidth(width: number) {
59		if (currentWindowWidth === width) return;
60		currentWindowWidth = width;
61		await getCurrentWindow().setSize(new LogicalSize(width, WINDOW_HEIGHT));
62		lastMonitorX = null;
63		lastMonitorY = null;
64		await repositionToCurrentMonitor();
65	}
66	
67	async function showVoiceControlWindow() {
68		await repositionToCurrentMonitor();
69		await getCurrentWindow().show();
70	}
71	
72	async function hideVoiceControlWindow() {
73		await getCurrentWindow().hide();
74	}
75	
76	async function repositionToCurrentMonitor() {
77		const cursor = await cursorPosition();
78		const monitor = await monitorFromPoint(cursor.x, cursor.y);
79		if (!monitor) return;
80	
81		const pos = monitor.position.toLogical(monitor.scaleFactor);
82		const size = monitor.size.toLogical(monitor.scaleFactor);
83	
84		if (pos.x === lastMonitorX && pos.y === lastMonitorY) return;
85		lastMonitorX = pos.x;
86		lastMonitorY = pos.y;
87	
88		const x = pos.x + (size.width - currentWindowWidth) / 2;
89		const y = pos.y + size.height - WINDOW_HEIGHT - BOTTOM_PADDING;
90	
91		await getCurrentWindow().setPosition(new LogicalPosition(x, y));
92	}
93	
94	export default function VoiceControl() {
95		const settings = useSettings();
96		const [isRecording, setIsRecording] = createSignal(false);
97		const [loading, setLoading] = createSignal(false);
98		const [currentShortcut, setCurrentShortcut] = createSignal<string | null>(null);
99		const [selectedMicrophone, setSelectedMicrophone] = createSignal<string | null>(null);
100		const [muteMediaWhileRecording, setMuteMediaWhileRecording] = createSignal(false);
101		const [audioLevel, setAudioLevel] = createSignal(0);
102		const [waveOffset, setWaveOffset] = createSignal(0);
103		const [isOnboardingComplete, setIsOnboardingComplete] = createSignal(false);
104		const [isLearningActive, setIsLearningActive] = createSignal(false);
105	
106		createEffect(() => {
107			if (!isRecording()) return;
108			const intervalId = setInterval(() => {
109				setWaveOffset((o) => (o + 1) % WAVE_PATTERN.length);
110			}, WAVE_STEP_MS);
111			onCleanup(() => clearInterval(intervalId));
112		});
113	
114		const barHeight = (index: number) => {
115			if (loading()) return BAR_BASE_HEIGHT;
116			const factor = WAVE_PATTERN[(waveOffset() + index) % WAVE_PATTERN.length]!;
117			const amplitude = BAR_IDLE_AMPLITUDE + audioLevel() * BAR_VOICE_SCALE;
118			return Math.min(BAR_MAX_HEIGHT, BAR_BASE_HEIGHT + factor * amplitude);
119		};
120		const [recordingMode, setRecordingMode] = createSignal<"toggle" | "hold" | null>(null);
121		let isStopping = false;
122		let isStarting = false;
123		let activeAppBundleId: string | null = null;
124		let activeDomain: string | null = null;
125	
126		const canUseShortcut = () => isOnboardingComplete() || isLearningActive();
127	
128		const toggleRecording = () => {
129			if (!canUseShortcut()) return;
130			if (isStarting || isStopping) return;
131	
132			if (isRecording()) {
133				if (recordingMode() !== "toggle") return;
134				stopRecording();
135			} else {
136				startRecording("toggle");
137			}
138		};
139	
140		const startHoldToSpeakRecording = () => {
141			if (!canUseShortcut()) return;
142			if (isStarting || isStopping || isRecording()) return;
143			startRecording("hold");
144		};
145	
146		const stopHoldToSpeakRecording = () => {
147			if (!canUseShortcut()) return;
148			if (isStarting || isStopping || !isRecording()) return;
149			if (recordingMode() !== "hold") return;
150			stopRecording();
151		};
152	
153		const registerShortcuts = async (toggleShortcut: string, holdShortcut: string) => {
154			const toggleHotkey = { hotkey: toggleShortcut, onPressed: toggleRecording };
155			const holdHotkey = {
156				hotkey: holdShortcut,
157				onPressed: startHoldToSpeakRecording,
158				onReleased: stopHoldToSpeakRecording,
159			};
160			const hotkeys = toggleShortcut === holdShortcut ? [toggleHotkey] : [toggleHotkey, holdHotkey];
161	
162			await registerDictationHotkeys(hotkeys);
163			setCurrentShortcut(`${toggleShortcut}|${holdShortcut}`);
164		};
165	
166		const unregisterShortcuts = async () => {
167			if (currentShortcut() === null) return;
168			await unregisterDictationHotkey();
169			setCurrentShortcut(null);
170		};
171	
172		onMount(async () => {
173			await repositionToCurrentMonitor();
174			const repositionInterval = setInterval(repositionToCurrentMonitor, 1000);
175			onCleanup(() => clearInterval(repositionInterval));
176	
177			const settings = await loadSettings();
178			let hotkey = settings.hotkey;
179			if (!isValidHotkey(hotkey)) {
180				hotkey = DEFAULT_HOTKEY;
181				await updateHotkey(hotkey);
182			}
183			let holdToSpeakHotkey = settings.holdToSpeakHotkey;
184			if (!isValidHotkey(holdToSpeakHotkey)) {
185				holdToSpeakHotkey = DEFAULT_HOLD_TO_SPEAK_HOTKEY;
186				await updateHoldToSpeakHotkey(holdToSpeakHotkey);
187			}
188			setSelectedMicrophone(settings.selectedMicrophoneId);
189			setMuteMediaWhileRecording(settings.muteMediaWhileRecording);
190			setIsOnboardingComplete(settings.onboardingComplete);
191			if (settings.onboardingComplete) {
192				await registerShortcuts(hotkey, holdToSpeakHotkey);
193			}
194	
195			const unlistenSettings = await listen("settings-changed", async () => {
196				const newSettings = await loadSettings();
197				const newHotkey = isValidHotkey(newSettings.hotkey) ? newSettings.hotkey : DEFAULT_HOTKEY;
198				const newHoldToSpeakHotkey = isValidHotkey(newSettings.holdToSpeakHotkey)
199					? newSettings.holdToSpeakHotkey
200					: DEFAULT_HOLD_TO_SPEAK_HOTKEY;
201				const wasOnboarding = !isOnboardingComplete();
202				const nowComplete = newSettings.onboardingComplete;
203				const shouldRegisterShortcuts = nowComplete || isLearningActive();
204				const shortcutKey = `${newHotkey}|${newHoldToSpeakHotkey}`;
205				if (
206					shouldRegisterShortcuts &&
207					(shortcutKey !== currentShortcut() || (wasOnboarding && nowComplete))
208				) {
209					await registerShortcuts(newHotkey, newHoldToSpeakHotkey);
210				} else if (!shouldRegisterShortcuts) {
211					await unregisterShortcuts();
212				}
213				setSelectedMicrophone(newSettings.selectedMicrophoneId);
214				setMuteMediaWhileRecording(newSettings.muteMediaWhileRecording);
215				setIsOnboardingComplete(newSettings.onboardingComplete);
216			});
217	
218			const unlistenAudio = await listen<number>("audio-level", (event) => {
219				setAudioLevel(event.payload);
220			});
221	
222			const unlistenLearning = await listen<boolean>("learning-step-active", async (event) => {
223				const active = event.payload;
224				setIsLearningActive(active);
225				const newSettings = await loadSettings();
226				const newHotkey = isValidHotkey(newSettings.hotkey) ? newSettings.hotkey : DEFAULT_HOTKEY;
227				const newHoldToSpeakHotkey = isValidHotkey(newSettings.holdToSpeakHotkey)
228					? newSettings.holdToSpeakHotkey
229					: DEFAULT_HOLD_TO_SPEAK_HOTKEY;
230				if (active || isOnboardingComplete()) {
231					const shortcutKey = `${newHotkey}|${newHoldToSpeakHotkey}`;
232					if (shortcutKey !== currentShortcut()) {
233						await registerShortcuts(newHotkey, newHoldToSpeakHotkey);
234					}
235				} else {
236					await unregisterShortcuts();
237				}
238			});
239	
240			onCleanup(() => {
241				unlistenSettings();
242				unlistenAudio();
243				unlistenLearning();
244			});
245		});
246	
247		onCleanup(async () => {
248			if (isRecording()) {
249				await cancelRecording();
250			}
251			await unregisterEscapeShortcut();
252			await unregisterDictationHotkey();
253			setCurrentShortcut(null);
254		});
255	
256		const stopRecording = async () => {
257			if (isStopping) return;
258			if (!isRecording()) return;
259	
260			logDiagnostic("info", "voice", "stop_recording_started", {
261				mode: recordingMode(),
262			});
263			isStopping = true;
264			setIsRecording(false);
265			setRecordingMode(null);
266			await unregisterEscapeShortcut();
267			await setWindowWidth(WINDOW_WIDTH_COMPACT);
268	
269			const completed = await Result.tryPromise(async () => {
270				const filePath = await stopRecordingWithDevice();
271				if (Result.isError(filePath)) {
272					logDiagnostic("error", "voice", "stop_recording_failed", errorFields(filePath.error));
273					return;
274				}
275				await restoreMediaAfterRecording();
276	
277				setLoading(true);
278	
279				const bundleId = activeAppBundleId;
280				const domain = activeDomain;
281				activeAppBundleId = null;
282				activeDomain = null;
283				const result = await transcribeAudio(
284					filePath.value,
285					bundleId,
286					domain,
287					settings().defaultStyle
288				);
289				if (Result.isError(result)) {
